function useSmoothScroll() {
  return (e, href) => {
    e.preventDefault();
    const target = document.querySelector(href);
    if (target) {
      const headerOffset = 80;
      window.scrollTo({ top: target.offsetTop - headerOffset, behavior: 'smooth' });
    }
  };
}

